var getWeatherChange = (index, change) => {
  let shift = 0;
  switch (roll(change)) {
    case 1:
      shift = 1;
      break;
    case 2:
      shift = -2;
      break;
    case 3:
    case 4:
      shift = -1;
      break;
    default:
      break;
  }
  return wrap(index, 0, 19, shift);
};
var getWeatherChangeAdv = (index, change, climateZone, subZone) => {
  let shift = 0;
  switch (roll(change)) {
    case 1:
      shift = 1;
      break;
    case 2:
      if (subZone == 0 && (climateZone == 3 || climateZone == 4)) {
        shift = -1;
      } else if (subZone == 0 && climateZone == 5) {
        shift = 2;
      } else if (subZone == 1 && (climateZone == 0 || climateZone == 2 || climateZone == 3 || climateZone == 4)) {
        shift = -1;
      } else if (subZone == 1 && climateZone == 5) {
        shift = 1;
      } else {
        shift = -2;
      }
      break;
    case 3:
      if (climateZone != 4) {
        shift = -1;
      }
      break;
    case 4:
      if (subZone == 0 && climateZone == 1) {
        shift = -1;
      } else if (subZone == 0 && climateZone == 5) {
        shift = -2;
      } else if (subZone == 1 && (climateZone != 3 && climateZone != 4)) {
        shift = -1;
      } else {
        shift = -1;
      }
      break;
    default:
      break;
  }
  return wrap(index, 0, 19, shift);
};
var getChangeDie = (wDir, prevW, wForce, precip) => {
  let dieTypes = [4, 6, 8, 10, 12];
  let typeIndex = 2;
  if (wDir == prevW) {
    typeIndex++;
  } else if (Math.abs(prevW - wDir) == 3) {
    typeIndex += -2;
  } else if (Math.abs(prevW - wDir) == 2 || Math.abs(prevW - wDir) == 4) {
    typeIndex--;
  }
  if (wForce < 2) {
    typeIndex++;
  } else if (wForce > 2) {
    typeIndex--;
  }
  if (precip == 2 || precip == 4 || precip == 6) {
    typeIndex--;
  } else if (precip == 5 || precip == 7 || precip == 9) {
    typeIndex++;
  }
  return dieTypes[clamp(typeIndex, 0, 4)];
};
var getPrecipitationType = (pSeason, pZone, pTemp, precip) => {
  let precipType = roll(100);
  switch (precip) {
    case 2:
    case 4:
    case 5:
    case 6:
    case 7:
    case 9:
      switch (pTemp) {
        case 5:
          if (precipType <= 50) {
            return "freezing snow";
          } else if (precipType <= 70) {
            return "hail/ice";
          } else {
            return "sleet";
          }
          break;
        case 4:
          if (precipType <= 30) {
            return "cold sleet";
          } else if (precipType <= 40) {
            return "hail";
          } else if (precipType <= 90) {
            return "snow";
          } else {
            return "freezing rain";
          }
          break;
        case 3:
          if (pZone == 1 && (pSeason == 0 || pSeason == 2) && precipType <= 10) {
            return "hail";
          }
          break;
        default:
          return "";
          break;
      }
      break;
    default:
      return "";
      break;
  }
  return "";
};
var cloudPrecipitationName = ["Clear and dry", "Cloudy but dry", "Cloudy with showers", "Overcast but dry", "Overcast with snow or hail showers", "Overcast with continuous snow", "Overcast with showers", "Overcast with continuous rain", "Foggy or misty", "Cloudy with thunderstorm"];
var getCloudPrecipitation = (cloudPrecipitation) => cloudPrecipitationName[cloudPrecipitation];
var subjectiveTemperatureName = ["**Sweltering**", "**Hot**", "Warm", "Cool", "Cold", "**Freezing**"];
var subjectiveTemperatureValues = [
  [">35\xB0C", "26\xB0C-35\xB0C", "16\xB0C-25\xB0C", "10\xB0C-15\xB0C", "1\xB0C-10\xB0C", "\u22640\xB0C"],
  [">95\xB0F", "79\xB0F-95\xB0F", "61\xB0F-77\xB0F", "50\xB0F-59\xB0F", "34\xB0F-50\xB0F", "\u226432\xB0F"]
];
var getSubjectiveTemperature = (temperature, units) => `${subjectiveTemperatureName[temperature]} at ${subjectiveTemperatureValues[units][temperature]}`;
var getHazard = (temperature) => temperature == 0 || temperature == 1 || temperature == 5 ? " \u26A0" : "";
var generateWeather = (settings, days) => {
  let result = "";
  let day = settings.day;
  let month = settings.month;
  let year = settings.year;
  let season = getSeasonExact(day, month);
  let index = settings.change == -1 ? weatherClimateZoneStart[settings.climateZone][season] : settings.change;
  let useadv = settings.useadv;
  let subzone = settings.subzone;
  let elevation = settings.elevation;
  let shadow = settings.shadow;
  let prevwind = settings.prevwind;
  let windshadow = settings.windshadow;
  for (let i = 0; i < days; i++) {
    let moonPhase = getMoonPhaseProgress(day);
    let daylight = getDaylight(settings.latitude, season);
    result += `##### ${day} ${monthName[month]} TR${year} (${seasonName[season]})
`;
    result += `**Dawn: ${getTime(daylight[0])}, Day: ${getTimeSpan(daylight[1], daylight[2])}, Dusk: ${getTime(daylight[3])}, Night: ${getTimeSpan(daylight[4], daylight[5])}, Moon: ${getMoonPhase(moonPhase[0], moonPhase[1])}**
`;
    for (let w = 0; w < 6; w++) {
      let daylight2 = isDay(settings.latitude, season, w * 4);
      let subjectiveTemperature = daylight2 ? weatherSubjectiveTemperatureDay[settings.climateZone][season][index] : weatherSubjectiveTemperatureNight[settings.climateZone][season][index];
      if (useadv) {
        subjectiveTemperature + (daylight2 ? weatherSubjectiveTemperatureDayMod[subjectiveTemperature][elevation] : weatherSubjectiveTemperatureNightMod[subjectiveTemperature][elevation]);
      }
      let cloudPrecipitation = weatherCloudPrecipitation[settings.climateZone][season][index];
      if (useadv) {
        cloudPrecipitation + weatherPrecipitationShadow[cloudPrecipitation][shadow];
      }
      let windDirection = weatherWindDirection[settings.climateZone][season][index];
      let windForce = weatherWindForce[settings.climateZone][season][index];
      if (useadv && windshadow && windForce > 0) {
        windForce -= 1;
      }
      let foggy = cloudPrecipitation == 8;
      let precipTypeString = ``;
      let precipString = ``;
      if (useadv) {
        precipString = `${getCloudPrecipitation(cloudPrecipitation)}`;
        precipTypeString = `${getPrecipitationType(season, settings.climateZone, subjectiveTemperature, cloudPrecipitation)}`;
        if (precipTypeString != "") {
          precipString = precipString.replace("with showers", `${precipTypeString} showers`).replace("with snow or hail showers", `${precipTypeString} showers`).replace("continuous snow", `continuous ${precipTypeString}`).replace("continuous rain", `continuous ${precipTypeString}`);
        }
        result += `- *${getTimeSpan(w * 4, w * 4 + 4)}:* ${getHazard(subjectiveTemperature)} ${getSubjectiveTemperature(subjectiveTemperature, settings.units)}, ${precipString}, ${getWind(windDirection, windForce, foggy, settings.units)}
`;
      } else {
        result += `- *${getTimeSpan(w * 4, w * 4 + 4)}:* ${getHazard(subjectiveTemperature)} ${getSubjectiveTemperature(subjectiveTemperature, settings.units)}, ${getCloudPrecipitation(cloudPrecipitation)}, ${getWind(windDirection, windForce, foggy, settings.units)}
`;
      }
      if (useadv) {
        index = getWeatherChangeAdv(index, getChangeDie(windDirection, prevwind, windForce, cloudPrecipitation), settings.climateZone, subzone);
      } else {
        index = getWeatherChange(index, weatherChange[settings.climateZone][season][index]);
      }
    }
    result += "\n";
    day++;
    if (day > 30) {
      day = 1;
      if (month + 1 > 11) {
        month = 0;
        year++;
      } else {
        month++;
      }
    }
    season = getSeasonExact(day, month);
  }
  fieldDay.setValue((settings.day = day).toString());
  fieldMonth.setValue((settings.month = month).toString());
  fieldYear.setValue((settings.year = year).toString());
  settings.change = index;
  return result;
};
